css:
.btn-pill {
  border-radius: var(--radius-full, 9999px);
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: inherit;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  box-sizing: border-box;
  border: 1px solid rgba(255, 255, 255, 0.18);
  outline: none;
  background: var(--primary, #2563eb);
  color: var(--canvas, #ffffff);
  min-height: 40px;
  padding: 0.6rem 1.35rem;
  font-size: 0.9rem;
  box-shadow: 0 4px 12px -2px rgba(0, 0, 0, 0.14), inset 0 1px 0 rgba(255, 255, 255, 0.22);
  transition: transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.18s ease;
  will-change: transform;
}

.btn-primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px -2px rgba(0, 0, 0, 0.20), inset 0 1px 0 rgba(255, 255, 255, 0.35);
}

.btn-primary:active:not(:disabled) {
  transform: scale(1.03, 0.94);
  box-shadow: 0 2px 4px -1px rgba(0, 0, 0, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.12);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--primary, #2563eb);
  outline-offset: 2px;
}
